import { createHash } from 'node:crypto';
const manifest = await Bun.file('docs/mobile-decision-report/CANDIDATE-MANIFEST.json').json();
const canonical = JSON.stringify(manifest.files.map(item => Object.fromEntries(Object.keys(item).sort().map(key => [key, item[key]]))));
const digest = createHash('sha256').update(canonical, 'utf8').digest('hex');
console.log(JSON.stringify({ declared_digest: manifest.digest, recomputed_digest: digest, matches: digest === manifest.digest, ascii_only: /^[\u0000-\u007F]*$/.test(canonical) }));

