import { syntheticMobileInput, SYNTHETIC_NOW_MS } from './src/mobile-decision-report/fixtures';
import { exportMobileDecisionHtml, exportMobileDecisionJson } from './src/mobile-decision-report/export';
import { projectMobileDecisionReport } from './src/mobile-decision-report/report';
const input = syntheticMobileInput('fresh');
input.origin = 'local_import';
input.dex_report.source = 'okx_authenticated';
const original = 'Fonte\u00b7secundaria\u2013curta\u2014longa & <tag>';
input.dex_report.tokenA.metadataSource = original;
const options = { now_ms: SYNTHETIC_NOW_MS };
const projection = projectMobileDecisionReport(input, options);
const html = exportMobileDecisionHtml(input, options);
const json = JSON.parse(exportMobileDecisionJson(input, options));
console.log(JSON.stringify({
  accepted: true,
  imported_notice: html.includes('Dados importados'),
  banned_rendered_codepoints: [...new Set([...html].filter(c => /[\u00b7\u2013\u2014]/.test(c)).map(c => 'U+' + c.codePointAt(0).toString(16).toUpperCase()))],
  sanitized_escaped_display: html.includes('Fonte/secundaria-curta-longa &amp; &lt;tag&gt;'),
  json_source_preserved: json.observed.dex.tokenA.metadataSource === original,
  input_source_preserved: input.dex_report.tokenA.metadataSource === original,
  projection_unchanged: JSON.stringify(json) === JSON.stringify(projection),
  binding_preserved: /^[0-9a-f]{64}$/.test(json.snapshot.facts_sha256) && json.snapshot.facts_sha256 === projection.snapshot.facts_sha256
}));

